// Deploy the bundled Worker script (ES module format) to overwrite java-sql-ai-tutorial worker
const workerB64 = "";
const workerCode = atob(workerB64);

// Convert decoded string to Uint8Array
const bytes = new Uint8Array(workerCode.length);
for (let i = 0; i < workerCode.length; i++) bytes[i] = workerCode.charCodeAt(i);

const metadata = {
  main_module: "worker.js",
  compatibility_date: "2024-09-24",
  bindings: []
};

const boundary = "----WorkerDeploy" + Date.now();

async () => {
  const metaPart = "--" + boundary + "\r\n" +
    'Content-Disposition: form-data; name="metadata"\r\n' +
    "Content-Type: application/json\r\n\r\n" +
    JSON.stringify(metadata) + "\r\n";
  const fileHeader = "--" + boundary + "\r\n" +
    'Content-Disposition: form-data; name="worker.js"; filename="worker.js"\r\n' +
    "Content-Type: application/javascript+module\r\n\r\n";
  const closing = "\r\n--" + boundary + "--\r\n";

  const enc = new TextEncoder();
  const head = enc.encode(fileHeader);
  const metaEnc = enc.encode(metaPart);
  const tail = enc.encode(closing);
  const total = metaEnc.length + head.length + bytes.length + tail.length;
  const body = new Uint8Array(total);
  let off = 0;
  body.set(metaEnc, off); off += metaEnc.length;
  body.set(head, off); off += head.length;
  body.set(bytes, off); off += bytes.length;
  body.set(tail, off); off += tail.length;

  let bodyStr = "";
  for (let i = 0; i < total; i++) bodyStr += String.fromCharCode(body[i]);

  const r = await cloudflare.request({
    method: "PUT",
    path: `/accounts/${accountId}/workers/scripts/java-sql-ai-tutorial`,
    body: bodyStr,
    contentType: "multipart/form-data; boundary=" + boundary,
    rawBody: true
  });
  return { success: r.success, status: r.status, errors: r.errors, result: r.result };
}
